function csvparse(s, a,    i,c,n,quoted,field) {
    delete a
    n=1; field=""; quoted=0
    for (i=1; i<=length(s); i++) {
        c=substr(s,i,1)
        if (quoted) {
            if (c=="\"") {
                if (substr(s,i+1,1)=="\"") { field=field "\""; i++ }
                else quoted=0
            } else field=field c
        } else if (c=="\"") quoted=1
        else if (c==",") { a[n++]=field; field="" }
        else field=field c
    }
    a[n]=field
    return n
}
function cents(s,    a,n,w,f,d) {
    gsub(/,/,"",s)
    n=split(s,a,"."); w=a[1]+0; f=(n>1?a[2]:"")
    while (length(f)<2) f=f "0"
    d=substr(f,1,2)+0
    if (length(f)>=3 && substr(f,3,1)>="5") d++
    return w*100+d
}
function money(c,    w,f) {
    w=int(c/100); f=c-w*100
    if (f<0) f=-f
    return w "." sprintf("%02d",f)
}
function trim(s) { sub(/^[[:space:]]+/,"",s); sub(/[[:space:]]+$/,"",s); return s }
function bankdate(s) { return substr(s,7,4) "-" substr(s,4,2) "-" substr(s,1,2) }
BEGIN { FS="\t" }
FILENAME ~ /ledger\.csv$/ {
    if (FNR==1) next
    sub(/\r$/, "")
    n=csvparse($0,f)
    id=f[1]; date=f[2]; amt=cents(f[4])
    ledger_rows++; ledger_total+=amt
    ledger[id]=1; ldate[id]=date; lamt[id]=amt
    next
}
FILENAME ~ /bank\.tsv$/ {
    if (FNR==1) next
    sub(/\r$/, "")
    ref=toupper(trim($1)); date=bankdate($2); amt=cents($4)
    key=ref "\034" date "\034" amt
    if (key in seen) { duplicates++; next }
    seen[key]=1
    bank_rows++; bank_total+=amt
    bank[ref]=1; bdate[ref]=date; bamt[ref]=amt
    next
}
END {
    for (id in ledger) {
        if (id in bank) {
            if (lamt[id]==bamt[id] && ldate[id]==bdate[id]) matched++
            else {
                if (lamt[id]!=bamt[id]) { amount_ids[++na]=id }
                if (ldate[id]!=bdate[id]) { date_ids[++nd]=id }
            }
        } else missing_bank[++nmb]=id
    }
    for (id in bank) if (!(id in ledger)) missing_ledger[++nml]=id

    # Sort each detail group lexically (transaction ids have a common format).
    for (i=2;i<=na;i++) { x=amount_ids[i]; j=i-1; while(j>=1 && amount_ids[j]>x) {amount_ids[j+1]=amount_ids[j];j--} amount_ids[j+1]=x }
    for (i=2;i<=nd;i++) { x=date_ids[i]; j=i-1; while(j>=1 && date_ids[j]>x) {date_ids[j+1]=date_ids[j];j--} date_ids[j+1]=x }
    for (i=2;i<=nmb;i++) { x=missing_bank[i]; j=i-1; while(j>=1 && missing_bank[j]>x) {missing_bank[j+1]=missing_bank[j];j--} missing_bank[j+1]=x }
    for (i=2;i<=nml;i++) { x=missing_ledger[i]; j=i-1; while(j>=1 && missing_ledger[j]>x) {missing_ledger[j+1]=missing_ledger[j];j--} missing_ledger[j+1]=x }

    print "ledger_rows: " ledger_rows
    print "bank_rows: " bank_rows
    print "duplicate_bank_rows: " duplicates
    print "ledger_total: " money(ledger_total)
    print "bank_total: " money(bank_total)
    print "matched: " matched
    print "amount_mismatch: " na
    for (i=1;i<=na;i++) { id=amount_ids[i]; print "  " id " ledger=" money(lamt[id]) " bank=" money(bamt[id]) }
    print "date_mismatch: " nd
    for (i=1;i<=nd;i++) { id=date_ids[i]; print "  " id " ledger=" ldate[id] " bank=" bdate[id] }
    print "missing_in_bank: " nmb
    for (i=1;i<=nmb;i++) print "  " missing_bank[i]
    print "missing_in_ledger: " nml
    for (i=1;i<=nml;i++) print "  " missing_ledger[i]
}
AWK
awk -f /home/eval/recon/reconcile.awk /home/eval/recon/ledger.csv /home/eval/recon/bank.tsv > /home/eval/recon/out/reconciliation.txt
cat /home/eval/recon/out/reconciliation.txt

